import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class ElitisticListPopulation_ElitisticListPopulation_TriageGen1Test {





    @Test
    public void testSetAndGetElitismRate() {
        int populationLimit = 5;
        double initialRate = 0.1;
        double newRate = 0.5;
        ElitisticListPopulation population = new ElitisticListPopulation(populationLimit, initialRate);

        assertEquals(initialRate, population.getElitismRate(), 1e-9);

        population.setElitismRate(newRate);
        assertEquals(newRate, population.getElitismRate(), 1e-9);
    }


}

